import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';const m=JSON.parse(fs.readFileSync(new URL('../prototype-page-map.json',import.meta.url)));test('frozen prototype maps all 69 routes without claiming real verification',()=>{assert.equal(m.count,69);assert.equal(new Set(m.pages.map(x=>x.page_id)).size,69);assert.equal(m.pages.filter(x=>x.page_id.startsWith('CUS-')).length,30);assert.ok(m.pages.every(x=>x.real_verified==='NO'));for(const id of['CUS-005','CUS-006','CUS-012','CUS-013','CUS-014'])assert.ok(m.pages.some(x=>x.page_id===id))});
